import sys

def find_fingering(n, notes):
    if n == 1:
        return [1]

    fingers = [0] * n
    fingers[0] = 1

    for i in range(1, n):
        if notes[i] > notes[i - 1]:
            if fingers[i - 1] == 5:
                return -1
            fingers[i] = fingers[i - 1] + 1
        elif notes[i] < notes[i - 1]:
            if fingers[i - 1] == -1:
                return -1
            fingers[i] = fingers[i - 2] - 1 if i >= 2 else 5
        else:
            if fingers[i - 1] == 5:
                return -2
            fingers[i] = fingers[i - 1] + 1 if fingers[i - 1] != 5 else 1

    return fingers

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    notes = list(map(int, input[1:]))
    result = find_fingering(n, notes)
    if result == -1 or result == -2:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
